package com.bank.atm;

import java.util.Arrays;
import java.util.logging.Logger;

public class NoteDispenser {

    private static final Logger log = Logger.getLogger(NoteDispenser.class.getName());

    public int minNotes(int[] denominations, int amount) {
        int[] dp = new int[amount + 1];
        Arrays.fill(dp, amount + 1);                   // sentinel = unreachable
        dp[0] = 0;                                     // zero amount ⇒ zero notes
        for (int a = 1; a <= amount; a++) {
            for (int coin : denominations) {
                if (coin <= a) {
                    dp[a] = Math.min(dp[a], dp[a - coin] + 1); // relax
                }
            }
        }
        int result = dp[amount] > amount ? -1 : dp[amount];
        final int r = result;
        if (r == -1) log.warning(() -> "Amount " + amount + " cannot be dispensed");
        else log.info(() -> "Amount " + amount + " needs minimum " + r + " notes");
        return result;
    }
}
