package com.bank.atm;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class CoinChangeDemo {

    private static final Logger log = Logger.getLogger(CoinChangeDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — ATM Note Dispenser (Coin Change)");
        int[] notes = {1, 2, 5};
        NoteDispenser dispenser = new NoteDispenser();
        log.info("11 → " + dispenser.minNotes(notes, 11)); // 3 (5+5+1)
        log.info("3 with {2} → " + dispenser.minNotes(new int[]{2}, 3)); // -1
    }
}
